import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse(`{"title":"Command reference","description":"Find install, run, check, and build commands for Ershu's six repositories and this site.","frontmatter":{"page_id":"reference-commands","title":"Command reference","description":"Find install, run, check, and build commands for Ershu's six repositories and this site."},"headers":[],"relativePath":"en/reference/commands.md","filePath":"en/reference/commands.md","lastUpdated":1786289447000}`),c={name:"en/reference/commands.md"};function n(a,t,s,i,l,u){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="command-reference" tabindex="-1">Command reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command reference&quot;">​</a></h1><p>Run every command from the corresponding repository root. Check the current branch and working tree first; commands are not interchangeable between repositories.</p><h2 id="complete-local-environment" tabindex="-1">Complete local environment <a class="header-anchor" href="#complete-local-environment" aria-label="Permalink to &quot;Complete local environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Command</th><th>Success condition</th></tr></thead><tbody><tr><td>Install the locked backend bundle</td><td><code>uv sync --all-extras --frozen</code></td><td>Installation finishes without rewriting the lockfile</td></tr><tr><td>Start infrastructure</td><td><code>docker compose --env-file .env.compose up -d</code></td><td>Compose services start and health checks eventually pass</td></tr><tr><td>Show database heads</td><td><code>uv run ershu-db heads</code></td><td>The discoverable migration head is printed</td></tr><tr><td>Upgrade the database</td><td><code>uv run ershu-db upgrade head</code></td><td>The command finishes and the database reaches the current head</td></tr><tr><td>Start API</td><td><code>uv run ershu-api</code></td><td><code>http://127.0.0.1:8000/health</code> returns <code>ok</code></td></tr><tr><td>Start MCP</td><td><code>uv run ershu-mcp</code></td><td><code>http://127.0.0.1:8001/health</code> returns <code>ok</code></td></tr><tr><td>Start Worker</td><td><code>uv run ershu-worker</code></td><td>The process remains running and can claim queued work</td></tr><tr><td>Start scheduled polling</td><td><code>uv run ershu-api-poller</code></td><td>The process remains running and checks repositories on UTC schedules</td></tr><tr><td>Poll once</td><td><code>uv run ershu-api-poller --once</code></td><td>One pass completes, reports actionable results, and exits</td></tr></tbody></table><p>See <a href="/en/development/local-setup">Set up local development</a> for the complete order and current installation limits.</p><h2 id="backend-module-checks" tabindex="-1">Backend module checks <a class="header-anchor" href="#backend-module-checks" aria-label="Permalink to &quot;Backend module checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Repository</th><th>Tests</th><th>Code and format</th><th>Build</th></tr></thead><tbody><tr><td>Core</td><td><code>uv run pytest -m &quot;not integration&quot;</code></td><td><code>uv run ruff check src tests</code><br><code>uv run ruff format --check src tests</code></td><td><code>uv build --wheel</code></td></tr><tr><td>API</td><td><code>uv run --extra dev pytest -q</code></td><td><code>uv run --extra dev ruff check src tests</code><br><code>uv run --extra dev ruff format --check src tests</code></td><td><code>uv build --wheel</code></td></tr><tr><td>Worker</td><td><code>uv run pytest -q</code></td><td><code>uv run ruff check src tests scripts</code><br><code>uv run ruff format --check src tests scripts</code></td><td><code>uv build --wheel</code></td></tr><tr><td>MCP</td><td><code>uv run pytest -q</code></td><td><code>uv run ruff check src tests</code><br><code>uv run ruff format --check src tests</code></td><td><code>uv build --wheel</code></td></tr><tr><td>Composition</td><td><code>uv run pytest tests -q</code></td><td><code>uv run ruff check tests scripts</code><br><code>uv run ruff format --check tests scripts</code><br><code>uv run basedpyright --project pyrightconfig.json</code></td><td><code>uv run ershu-db heads</code></td></tr></tbody></table><p>Regular unit results do not replace tests that require external services. See <a href="/en/development/quality">Quality, commits, and pull requests</a> for selection guidance.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Command</th><th>Success condition</th></tr></thead><tbody><tr><td>Install from lockfile</td><td><code>npm ci</code></td><td>Installation finishes without changing <code>package-lock.json</code></td></tr><tr><td>Start development</td><td><code>npm run dev</code></td><td><code>http://localhost:3000</code> opens</td></tr><tr><td>Run tests</td><td><code>npm test</code></td><td>All Node.js tests pass</td></tr><tr><td>Check code and types</td><td><code>npm run lint</code></td><td>ESLint and TypeScript checks pass</td></tr><tr><td>Check formatting</td><td><code>npm run format:check</code></td><td>Prettier reports no files needing changes</td></tr><tr><td>Build production output</td><td><code>npm run build</code></td><td><code>dist/</code> is generated and the command exits successfully</td></tr><tr><td>Preview output</td><td><code>npm run preview</code></td><td>The terminal shows a local address and the page opens</td></tr></tbody></table><h2 id="this-documentation-site" tabindex="-1">This documentation site <a class="header-anchor" href="#this-documentation-site" aria-label="Permalink to &quot;This documentation site&quot;">​</a></h2><p>Run these from the repository root:</p><table tabindex="0"><thead><tr><th>Goal</th><th>Command</th><th>Success condition</th></tr></thead><tbody><tr><td>Install</td><td><code>npm ci</code></td><td>Dependencies install from the lockfile</td></tr><tr><td>Write locally</td><td><code>npm run dev</code></td><td>A local address appears and both languages open</td></tr><tr><td>Check content</td><td><code>npm run check:content</code></td><td>Locale pairs, links, typography, and placeholders pass</td></tr><tr><td>Run all checks</td><td><code>npm run check</code></td><td>Content, formatting, and production build all pass</td></tr><tr><td>Preview output</td><td><code>npm run preview</code></td><td>Production output opens locally</td></tr></tbody></table><blockquote><p>Command sources: current manifests, README files, and CI. Consult the delivery report to see which commands were actually run while building this site.</p></blockquote>',14)])])}const m=e(c,[["render",n]]);export{p as __pageData,m as default};
